<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use App\Services\Marketing\{MarketingOptimization,MarketingSemanticOptimization,MarketingOneClickOptimization};use App\Models\MarketingAiRun;
class MarketingOptimizationController extends Controller {
 private function reader(?string $id):MarketingOptimization|MarketingSemanticOptimization {$semantic=$id?MarketingAiRun::whereKey($id)->where('action',MarketingSemanticOptimization::ACTION)->exists():config('marketing.optimization.semantic_enabled',true);return app($semantic?MarketingSemanticOptimization::class:MarketingOptimization::class);}
 public function oneClick(Request $r,string $project,string $film){$d=$r->validate(['request_id'=>'required|uuid','base_hash'=>'required|regex:/^[a-f0-9]{64}$/','run_id'=>'sometimes|nullable|uuid']);if(isset($d['run_id']))$this->reader($d['run_id'])->read($project,(int)$r->user()->id,$film,$d['run_id']);$run=app(MarketingOneClickOptimization::class)->start($project,(int)$r->user()->id,$film,$d['base_hash'],$d['request_id'],$d['run_id']??null);$s=app($run->action===MarketingSemanticOptimization::ACTION?MarketingSemanticOptimization::class:MarketingOptimization::class);return response()->json(['run'=>$s->present($run)])->header('Cache-Control','private, no-store');}
 public function show(Request $r,string $project,string $film){$s=$this->reader($r->query('run'));$run=$s->read($project,(int)$r->user()->id,$film,$r->query('run'));return response()->json(['run'=>$s->present($run)])->header('Cache-Control','private, no-store');}
 public function start(Request $r,string $project,string $film){$d=$r->validate(['recheck'=>'sometimes|boolean','request_id'=>'required|uuid','base_hash'=>'required|regex:/^[a-f0-9]{64}$/']);$s=app(MarketingOptimization::class);$run=$s->enqueue($project,(int)$r->user()->id,$film,$d['base_hash'],$d['request_id'],$d['recheck']??false);return response()->json(['run'=>$s->present($run)])->header('Cache-Control','private, no-store');}
 public function sample(Request $r,string $project,string $film,string $run,string $sample){$s=app(MarketingOptimization::class);$record=$s->read($project,(int)$r->user()->id,$film,$run);$item=collect($record->usage['evidence']['samples']??[])->firstWhere('id',$sample);abort_unless($item,404);$file=app(\App\Services\Marketing\MarketingVideoFiles::class)->file($item['path'],$item['sha256']);return response()->file($file,['Content-Type'=>'image/jpeg','Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
 public function adopt(Request $r,string $project,string $film){$d=$r->validate(['run_id'=>'required|uuid','request_id'=>'required|uuid','selected'=>'required|array|min:1|max:6','selected.*'=>'required|string|distinct','consent'=>'required|accepted','speech_consent'=>'sometimes|boolean']);$s=app(MarketingOptimization::class);$run=$s->read($project,(int)$r->user()->id,$film,$d['run_id']);$new=$s->adopt($run,$d['request_id'],$d['selected'],$d['speech_consent']??false);return response()->json(['film_id'=>$new->id,'url'=>route('marketing.workspace.show',['project'=>$project,'screen'=>'finished','film'=>$new->id])]);}
}
